function go(p,t=''){page=p;tab=t;filter='全部';query='';location.hash=p;render();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{if(location.hash.slice(1)!==page){page=location.hash.slice(1)||'home';tab='';filter='全部';query='';render()}});
function render(){if(!modules.some(m=>m[0]===page)&&page!=='home')page='home';const meta=modules.find(m=>m[0]===page);$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brandmark">${icon('leaf')}</div><div><b>乡约码上行</b><small>LIVE & WORK, NATURALLY</small></div></div><button class="navbutton ${page==='home'?'active':''}" data-go="home">${icon('home')}乡野首页</button><div class="navlabel">你的乡村生活</div>${modules.map((m,i)=>`<button class="navbutton ${page===m[0]?'active':''}" data-go="${m[0]}">${icon(m[0])}${m[1]}<span class="num">0${i+1}</span></button>`).join('')}<div class="sidebottom"><div class="sidequote">${icon('leaf')}把工作带进自然，<br>把日子过成喜欢的样子。</div><button class="profilemini" data-go="user"><span class="avatar">${esc(state.profile.name.slice(0,1))}</span><span style="text-align:left"><b>${esc(state.profile.name)}</b><br><small>${esc(state.profile.role)} · 演示身份</small></span></button></div></aside><div class="main"><header class="topbar"><button class="mobilemenu" data-action="menu" aria-label="打开六大板块导航">${icon('menu')}</button><span class="mobilebrand">乡约码上行</span><div class="crumb">乡约码上行 <span> / </span> ${meta?meta[1]:'乡野首页'}</div><div class="topright"><button class="location" data-go="map">${icon('pin')}浙江 · 安吉余村</button><span class="badge">交互演示版</span><button data-action="notifications" aria-label="查看通知">${icon('bell')}</button><button class="avatar" data-go="user" aria-label="个人中心">${esc(state.profile.name.slice(0,1))}</button></div></header><main class="content">${({home:home,user:userPage,desk:deskPage,map:travelPage,box:resourcePage,calendar:activityPage,community:communityPage}[page])()}<footer class="footer"><span>乡约码上行 · 让每一次抵达，都有归属</span><span>演示内容与价格 · 操作记录仅保存在当前浏览器</span></footer></main></div>`;bind()}
const heading=(title,sub,action='')=>`<div class="pageheading"><div><div class="eyebrow">${modules.find(m=>m[0]===page)?.[3]||'A LITTLE CLOSER TO NATURE'}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;
const btn=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const tabs=(values)=>`<div class="tabs">${values.map((t,i)=>`<button class="tab ${(tab||values[0])===t?'selected':''}" data-tab="${t}">${t}</button>`).join('')}</div>`;
const empty=(s,p)=>`<div class="empty">${icon('leaf')}<p>${s}</p>${p?`<button class="btn soft" data-go="${p}">去发现新的可能 ${icon('arrow')}</button>`:''}</div>`;
const tags=a=>a.map(t=>`<span class="tag">${esc(t)}</span>`).join('');
function home(){let active=state.bookings.filter(b=>!['已取消','已结束'].includes(b.status));return `${heading(`你好，${esc(state.profile.name)}，乡野在等你。`,'换一种节奏，让工作与生活在这里相遇。',`<div class="datepill">${icon('leaf')}在乡野，好好生活</div>`)}<section class="hero"><div class="heroart">${landscape()}</div><div class="herotext"><div class="herotag">WORK FROM ANYWHERE · BELONG SOMEWHERE</div><h2 class="serif">远方不必很远，<br>理想生活就在乡间。</h2><p>一张工位，一群同频的人，一段自在的日常。<br>在余村，开启你的下一站游牧生活。</p><button class="btn" data-go="map">探索我的乡村 ${icon('arrow')}</button></div></section><div class="sectiontitle"><h2>六种连接，一种向往的生活</h2><small>从抵达，到融入</small></div><div class="modules">${modules.map(m=>`<button class="module" data-go="${m[0]}"><span class="moduleicon">${icon(m[0])}</span><b>${m[1]}</b><small>${m[2]}</small></button>`).join('')}</div><div class="twocol"><section><div class="sectiontitle"><h2>在自然里，找一个好工位</h2><button class="textbtn" data-go="desk">查看全部 ${icon('arrow')}</button></div><div class="grid two">${spaces.slice(0,2).map(spaceCard).join('')}</div></section><section><div class="sectiontitle"><h2>我的乡野日程</h2><span class="status">从容安排每一天</span></div><div class="panel"><div class="inline">${icon('calendar')}<b>接下来的小期待</b></div>${active.length||state.events.length?`<div class="timeline">${active.slice(0,2).map(b=>`<div class="timelineitem"><small>${b.date} · ${b.time}</small><h3>${esc(b.name)}</h3><p>${b.seat} 号工位 · ${b.status}</p></div>`).join('')}${state.events.slice(0,2).map(id=>{let a=activities.find(a=>a.id===id);return `<div class="timelineitem"><small>${eventDate(a)} · ${a.time}</small><h3>${a.name}</h3><p>${a.place}</p></div>`}).join('')}</div>`:`<div class="timeline"><div class="timelineitem"><small>第一步 · 安顿工作</small><h3>选一张喜欢的工位</h3><p>预约后，你的安排会出现在这里</p></div><div class="timelineitem"><small>下一步 · 认识邻居</small><h3>参加一场在地活动</h3><p>让陌生的地方慢慢变成熟悉的日常</p></div></div>`}<button class="textbtn" style="margin-top:22px" data-go="calendar">发现乡村活动 ${icon('arrow')}</button></div><div class="notice">慢下来，也能走得更远。<br>今天，给自己留一点感受自然的时间。</div></section></div><div class="sectiontitle"><h2>和邻居一起，发现生活的小美好</h2><button class="textbtn" data-go="community">去社区逛逛 ${icon('arrow')}</button></div><div class="grid">${activities.map(activityCard).join('')}</div>`}
function spaceCard(s){return `<article class="card"><div class="art">${landscape('desk')}<span class="artlabel">${s.area} · ${s.place}</span></div><div class="cardbody"><div class="cardhead"><h3>${s.name}</h3></div><p>${s.desc}</p>${tags([s.net,...s.tags.slice(0,2)])}<div class="cardfoot"><span class="price">¥ ${s.price}<small> / 天</small></span>${btn('预约工位','book','','data-id="'+s.id+'"')}</div></div></article>`}
function deskPage(){return `${heading('把办公室，搬进自然里。','找到适合你的工作空间，让每一天都更专注。')}${tabs(['发现工位','我的预约'])}${tab==='我的预约'?`<div class="panel">${state.bookings.length?state.bookings.slice().reverse().map(b=>`<div class="record"><div><h3>${esc(b.name)} <span class="tag">${b.status}</span></h3><small>${b.date} · ${b.time} · ${b.seat} 号 · ¥${b.price}（演示，无实际扣费）</small></div><div class="recordactions">${b.status==='待签到'?btn('签到','booking-status','tiny',`data-id="${b.id}" data-next="使用中"`)+btn('取消预约','booking-status','secondary tiny',`data-id="${b.id}" data-next="已取消"`):b.status==='使用中'?btn('暂离工位','booking-status','soft tiny',`data-id="${b.id}" data-next="暂离中"`)+btn('结束使用','booking-status','secondary tiny',`data-id="${b.id}" data-next="已结束"`):b.status==='暂离中'?btn('返回工位','booking-status','tiny',`data-id="${b.id}" data-next="使用中"`):''}</div></div>`).join(''):empty('还没有预约，先选一个喜欢的工作空间吧。','desk')}</div>`:`<div class="filters"><input class="search" id="search" aria-label="搜索工位" placeholder="搜索空间、地点或设施" value="${esc(query)}">${['全部','静音专注','协作交流','独立会议'].map(t=>`<button class="chip ${filter===t?'selected':''}" data-filter="${t}">${t}</button>`).join('')}</div><div class="grid" id="results">${deskResults()}</div><div class="notice">预约流程：选择日期与时段 → 在线选座 → 确认预约 → 签到 / 暂离 / 结束使用。当前为演示签到，不启用人脸识别或摄像头。</div>`}`}
function deskResults(){return spaces.filter(s=>(filter==='全部'||s.area===filter)&&JSON.stringify(s).toLowerCase().includes(query.toLowerCase())).map(spaceCard).join('')||empty('没有找到符合条件的工位，试试其他关键词。')}
function travelPage(){return `${heading('下一站，住进向往的生活。','认识村庄，规划行程，找到同频的旅伴。')}${tabs(['发现乡村','行程规划','同行搭子','我的行程'])}${(tab||'发现乡村')==='发现乡村'?`<div class="grid">${villages.map(v=>`<article class="card"><div class="art">${landscape()}<span class="artlabel">${v.tag}</span></div><div class="cardbody"><h3>${v.name}</h3><p>${v.desc}</p>${tags(['网络 '+v.net+' Mbps','公交 / 自驾','民宿可选'])}<div class="cardfoot"><span class="price">¥ ${v.budget}<small> / 日参考</small></span>${btn('了解村庄','village','','data-id="'+v.id+'"')}</div></div></article>`).join('')}</div><div class="notice">村庄展示为产品演示资料，网络、住宿和交通信息未接入实时服务；行程按你的预算和偏好在本地生成。</div>`:tab==='行程规划'?`<div class="twocol"><form class="panel" id="trip-form"><h2>把时间留给喜欢的事情</h2><p class="intro">设置你的偏好，生成一份工作与休闲兼顾的乡村行程。</p><div class="formgrid"><label class="field">目的地<select name="village">${villages.map(v=>`<option value="${v.id}">${v.name}</option>`).join('')}</select></label><label class="field">出发日期<input type="date" name="date" min="${datePlus(0)}" value="${datePlus(1)}" required></label><label class="field">停留天数<select name="days"><option value="2">2 天 1 夜</option><option value="3" selected>3 天 2 夜</option><option value="5">5 天 4 夜</option></select></label><label class="field">每日预算（元）<input type="number" name="budget" min="100" max="5000" value="200" required></label><label class="field">旅行节奏<select name="pace"><option>工作与休闲平衡</option><option>专注远程办公</option><option>在地文化探索</option></select></label><label class="field">交通方式<select name="transport"><option>公共交通 + 村内步行</option><option>自驾 + 村内骑行</option></select></label></div><button class="btn">生成并保存行程 ${icon('arrow')}</button></form><div class="panel accentpanel"><div class="art" style="border-radius:10px">${landscape()}</div><h3 style="margin-top:20px">行程里，也要有留白。</h3><p class="intro">每天安排一段专注工作、一点自然体验，以及与当地人相遇的时间。生成后可以随时查看或删除。</p></div></div>`:tab==='同行搭子'?`<div class="grid">${[['林间','摄影 / 徒步','周末去余村，想走走竹林步道。'],['阿禾','设计 / 咖啡','平日远程办公，周末一起找灵感。'],['小麦','骑行 / 农事','想体验秋收，欢迎喜欢田野的朋友。']].map((x,i)=>`<article class="panel"><div class="posthead"><div class="avatar">${x[0][0]}</div><div><h3>${x[0]}</h3><small>余村 · 演示旅伴</small></div></div>${tags(x[1].split(' / '))}<p class="intro" style="margin-top:15px">${x[2]}</p>${btn(state.requests.some(r=>r.target===x[0])?'已发送邀请':'发起同行邀请','request','secondary',`data-kind="同行邀请" data-target="${x[0]}"`)}</article>`).join('')}</div><div class="notice">邀请会记录在「用户管理 → 我的申请」。演示旅伴不会收到真实消息。</div>`:`<div class="panel">${state.trips.length?state.trips.slice().reverse().map(t=>`<div class="record"><div><h3>${esc(t.name)} · ${t.days} 天</h3><small>${t.date} 出发 · ${esc(t.pace)} · 每日预算 ¥${t.budget}</small></div><div class="recordactions">${btn('查看行程','trip-detail','soft tiny',`data-id="${t.id}"`)}${btn('删除','delete-trip','secondary tiny',`data-id="${t.id}"`)}</div></div>`).join(''):empty('还没有计划。切换到「行程规划」，开始安排下一站。')}</div>`}`}
function resourcePage(){let view=tab||'资源集市';return `${heading('分享一点，生活丰富一点。','闲置交换、技能互助与设施维护，让社区资源流动起来。',btn('发布资源','publish-resource'))}${tabs(['资源集市','技能互助','公共设施','我的发布'])}${view==='公共设施'?`<div class="grid">${[['会议室投影','田野工作客厅 · 设备 A-01'],['共享打印机','社区服务站 · 设备 B-03'],['无线网络','竹间自习室 · 设备 C-02']].map((f,i)=>`<div class="panel"><span class="moduleicon">${icon('desk')}</span><h3>${f[0]}</h3><p class="intro">${f[1]}</p><span class="tag">演示状态：正常</span><div class="cardfoot">${btn('提交报修','repair','secondary',`data-target="${f[0]}"`)}</div></div>`).join('')}</div>`:`<div class="filters"><input id="search" class="search" aria-label="搜索资源" placeholder="搜索物品、技能或需求" value="${esc(query)}">${view==='资源集市'?['全部','闲置交换','技能互助'].map(t=>`<button class="chip ${filter===t?'selected':''}" data-filter="${t}">${t}</button>`).join(''):''}</div><div class="grid" id="results">${resourceResults()}</div>`}`}
function resourceResults(){let v=tab||'资源集市';return [...items,...state.listings].filter(i=>(v!=='我的发布'||i.mine)&&(v!=='技能互助'||i.kind==='技能互助')&&(filter==='全部'||i.kind===filter)&&JSON.stringify(i).includes(query)).map(i=>`<article class="panel"><div class="cardhead"><span class="moduleicon" style="margin:0 0 18px">${icon(i.kind==='技能互助'?'community':'box')}</span><span class="tag">${esc(i.kind)}</span></div><h3>${esc(i.name)}</h3><p class="intro" style="margin:12px 0">${esc(i.desc)}</p>${tags(i.tags||[i.kind])}<div class="cardfoot"><small>${esc(i.owner)} · ${esc(i.offer)}</small>${i.mine?btn('撤下','remove-listing','secondary tiny',`data-id="${i.id}"`):btn('申请'+(i.kind==='技能互助'?'互助':'交换'),'request','secondary tiny',`data-kind="${i.kind}" data-target="${esc(i.name)}"`)}</div></article>`).join('')||empty('暂时没有符合条件的资源，发布你的第一条信息吧。')}
function activityCard(a){return `<article class="card"><div class="art">${landscape(a.type==='农事体验'?'farm':'village')}<span class="artlabel">${a.type}</span></div><div class="cardbody"><h3>${a.name}</h3><p>${eventDate(a)} · ${a.time}<br>${a.place}</p><div class="cardfoot"><span class="price">${a.price?'¥ '+a.price:'免费'}<small>${a.price?' / 人':''}</small></span>${btn(state.events.includes(a.id)?'查看报名':'活动详情','event','secondary',`data-id="${a.id}"`)}</div></div></article>`}
function activityPage(){let v=tab||'乡村活动';return `${heading('走近乡村，从一起做件事开始。','参与在地活动，认养一份生长，让相遇留下来。',['数字游民公社','平台管理员'].includes(state.profile.role)?btn('发起活动','propose-event'):'')}${tabs(['乡村活动','云认养','我的参与'])}${v==='乡村活动'?`<div class="filters">${['全部','自然户外','社群共创','农事体验'].map(t=>`<button class="chip ${filter===t?'selected':''}" data-filter="${t}">${t}</button>`).join('')}</div><div class="grid">${activities.filter(a=>filter==='全部'||a.type===filter).map(activityCard).join('')}</div>`:v==='云认养'?`<div class="grid two">${[{id:'rice',name:'一小块稻田，一整季期待',desc:'余村共享农田 · 水稻 · 20 平方米',price:299},{id:'tea-tree',name:'认养一棵茶树，等待春天',desc:'安吉茶园 · 白茶 · 1 棵',price:199}].map(a=>`<article class="card"><div class="art" style="height:220px">${landscape('farm')}</div><div class="cardbody"><span class="tag">认养经济 · 演示项目</span><h3 style="margin-top:12px">${a.name}</h3><p>${a.desc}</p><div class="growth"><i style="width:65%"></i></div><small>示例生长阶段：日常养护 · 最近记录：观察叶色与土壤</small><div class="cardfoot"><span class="price">¥ ${a.price}<small> / 季</small></span>${btn(state.adoptions.includes(a.id)?'查看我的认养':'了解并认养','adopt','',`data-id="${a.id}"`)}</div></div></article>`).join('')}</div>`:`<div class="panel"><h3>活动报名</h3>${state.events.length?state.events.map(id=>activityRecord(id)).join(''):empty('还没有参与活动，来乡村认识新朋友吧。')}<h3 style="margin-top:24px">我的认养</h3>${state.adoptions.length?state.adoptions.map(id=>`<div class="record"><div><h3>${id==='rice'?'余村共享稻田':'安吉白茶树'}</h3><small>认养已记录 · 未产生付款 · 收益 ¥0</small></div>${btn('查看生长档案','adopt','soft tiny',`data-id="${id}"`)}</div>`).join(''):empty('认养一份生长，与乡村多一份连接。')}</div>`}`}
function activityRecord(id){let a=activities.find(x=>x.id===id);return `<div class="record"><div><h3>${a.name}</h3><small>${eventDate(a)} · ${a.time} · ${a.place}</small></div>${btn('取消报名','cancel-event','secondary tiny',`data-id="${id}"`)}</div>`}
function userPage(){let v=tab||'个人资料';return `${heading('每一种身份，都有自己的位置。','管理你的资料、角色与申请，留下乡村生活的足迹。')}${tabs(['个人资料','角色与认证','我的申请'])}${v==='个人资料'?`<div class="profilecard"><span class="avatar">${esc(state.profile.name.slice(0,1))}</span><div><h2>${esc(state.profile.name)}</h2><p>${esc(state.profile.bio)}</p>${tags([state.profile.role,'安吉 · 余村'])}</div></div><div class="twocol"><form class="panel" id="profile-form"><h3 style="margin-bottom:20px">编辑个人资料</h3><label class="field">昵称<input name="name" maxlength="20" value="${esc(state.profile.name)}" required></label><label class="field">我的技能<input name="skill" maxlength="100" value="${esc(state.profile.skill)}" required></label><label class="field">一句话介绍<textarea name="bio" maxlength="200">${esc(state.profile.bio)}</textarea></label><button class="btn">保存资料</button></form><div><div class="panel"><h3>我的生活足迹</h3><div class="record"><span>工位预约</span><b>${state.bookings.length} 次</b></div><div class="record"><span>活动参与</span><b>${state.events.length} 场</b></div><div class="record"><span>规划行程</span><b>${state.trips.length} 份</b></div><div class="record"><span>共享资源</span><b>${state.listings.length} 条</b></div></div><div class="notice">当前为单机交互演示。资料和操作仅保存在这个浏览器中，不上传身份证、密码或其他敏感认证材料。</div></div></div>`:v==='角色与认证'?`<div class="panel"><h3>切换演示角色</h3><p class="intro" style="margin-top:10px">对应论文中的五类用户。此处用于演示界面与业务分工，不作为真实登录或安全权限验证。</p><div class="rolegrid">${roles.map(r=>`<button class="chip ${state.profile.role===r?'selected':''}" data-action="role" data-role="${r}">${r}</button>`).join('')}</div><div class="summary" style="margin-top:20px">当前身份：${state.profile.role}<br>${{'数字游民':'可预约工位、规划行程、报名活动、交换资源与申请兼职。','当地村民':'可分享在地资源、发布认养动态，参与技能互助。','企业':'可提交企业认证、发布兼职项目，查看合作申请。','数字游民公社':'可发起活动、提交资源信息，参与社区运营。','平台管理员':'可查看社区审核队列、处理申请，查看运营统计。'}[state.profile.role]}</div>${btn('提交资格认证申请','certify','secondary')}${state.profile.role==='当地村民'?btn('发布认养动态','growth','soft'):''}<h3 style="margin-top:24px">我的认证记录</h3>${state.certs.length?state.certs.map(c=>`<div class="record"><span>${esc(c.org)} · ${esc(c.role)}</span><span class="tag">${esc(c.status)}</span></div>`).join(''):empty('尚未提交认证申请。')}</div>`:`<div class="panel">${state.requests.length?state.requests.slice().reverse().map(r=>`<div class="record"><div><h3>${esc(r.target)} <span class="tag">${esc(r.kind)}</span></h3><small>${esc(r.note||'期待与你一起共创乡村生活。')}<br>${esc(r.status)} · ${r.date}</small></div>${r.status==='待处理'?btn('撤回','withdraw','secondary tiny',`data-id="${r.id}"`):''}</div>`).join(''):empty('还没有申请记录。同行、交换、互助、报修和兼职申请会统一显示在这里。')}</div>`}`}
function communityPage(){let v=tab||'邻里广场',admin=state.profile.role==='平台管理员';return `${heading('在这里，遇见同频的邻居。','分享日常、寻找合作，一起建设有温度的社区。',btn('分享日常','post'))}${tabs(['邻里广场','兼职合作','社区公约','运营与审核'])}${v==='邻里广场'?`<div class="twocol"><div>${[...state.posts].reverse().concat(seedPosts).filter(p=>!state.hiddenPosts.includes(p.id)).map(postCard).join('')}</div><div><div class="panel accentpanel"><h3>我们相信，一点点连接的力量。</h3><p class="intro" style="margin-top:15px">尊重不同的生活方式，分享真实的在地体验。无论从哪里来，今天的你，都是这里的一位邻居。</p><button class="textbtn" data-tab="社区公约">阅读社区公约 ${icon('arrow')}</button></div><div class="sectiontitle"><h2>社区小事</h2></div><div class="panel"><h3>一起让公共空间更舒服</h3><p class="intro" style="margin-top:12px">离开工位前带走随身物品，把干净的桌面留给下一位邻居。</p><button class="textbtn" data-go="box">发现共享资源 ${icon('arrow')}</button></div></div></div>`:v==='兼职合作'?`<div class="sectiontitle"><small>项目内容与金额为演示信息，申请不会发送给真实企业。</small>${['企业','平台管理员'].includes(state.profile.role)?btn('发布项目','publish-job','secondary'):''}</div><div class="grid two">${[...jobs,...state.approvals.filter(a=>a.kind==='兼职项目'&&a.status==='已通过').map(a=>({id:a.id,name:a.title,company:a.org||'社区企业',pay:a.pay||'面议',skill:a.skill||'项目合作',desc:a.desc}))].map(j=>`<article class="panel"><span class="tag">远程协作</span><h3 style="margin:14px 0">${esc(j.name)}</h3><small>${esc(j.company)}</small><p class="intro" style="margin:15px 0">${esc(j.desc)}</p>${tags([j.skill])}<div class="cardfoot"><b style="color:#6d8559">${esc(j.pay)}</b>${btn('申请合作','request','',`data-kind="兼职合作" data-target="${esc(j.name)}"`)}</div></article>`).join('')}</div>`:v==='社区公约'?`<div class="panel">${[['尊重彼此的节奏','静音区域轻声交流，视频会议请使用独立空间。'],['让共享成为习惯','按时归还借用物品，交换前确认状态与交接方式。'],['与乡村友好相处','尊重村民的生活习惯，不随意进入农田和私人区域。'],['真实交流，善意表达','不发布虚假信息、广告骚扰与侵犯他人隐私的内容。'],['共同爱护自然','垃圾分类、节约资源，让来过的地方保持原来的美好。']].map((r,i)=>`<div class="rule"><span class="number">0${i+1}</span><div><h3>${r[0]}</h3><p>${r[1]}</p></div></div>`).join('')}<div style="margin-top:22px">${btn(state.readRules?'已阅读并承诺遵守':'我已阅读，愿意共同维护','read-rules',state.readRules?'soft':'')}</div></div>`:`${report()}<div class="panel"><div class="sectiontitle" style="margin-top:0"><h2>社区审核队列</h2><span class="tag">${admin?'管理员演示模式':'切换平台管理员可处理审核'}</span></div>${state.approvals.length?state.approvals.slice().reverse().map(a=>`<div class="record"><div><h3>${esc(a.title)} <span class="tag">${a.kind}</span></h3><small>${esc(a.desc)}<br>${esc(a.status)}</small></div>${admin&&a.status==='待审核'?`<div class="recordactions">${btn('通过','approve','tiny',`data-id="${a.id}" data-next="已通过"`)}${btn('驳回','approve','secondary tiny',`data-id="${a.id}" data-next="已驳回"`)}</div>`:''}</div>`).join(''):empty('暂无待审核内容。认证、活动和项目申请提交后会出现在这里。')}${admin?`<div class="sectiontitle"><h2>用户业务申请</h2></div>${state.requests.filter(r=>r.status==='待处理').map(r=>`<div class="record"><div><h3>${esc(r.target)}</h3><small>${esc(r.kind)} · ${esc(r.note)}</small></div><div class="recordactions">${btn('受理','handle-request','tiny',`data-id="${r.id}"`)}${btn('驳回','reject-request','secondary tiny',`data-id="${r.id}"`)}</div></div>`).join('')||empty('暂无待处理业务申请。')}`:''}</div>`}`}
function postCard(p){return `<article class="post"><div class="posthead"><span class="avatar">${esc(p.author[0])}</span><div><b>${esc(p.author)}</b><br><small>${esc(p.topic)} · ${p.date||'示例动态'}</small></div></div><h3 style="margin-bottom:11px">${esc(p.title)}</h3><p>${esc(p.body)}</p><div class="postfoot"><button data-action="like" data-id="${p.id}">${state.likes.includes(p.id)?'♥':'♡'} ${p.likes+(state.likes.includes(p.id)?1:0)} 份共鸣</button><button data-action="comment" data-id="${p.id}">留言 ${(state.comments[p.id]||[]).length}</button>${p.mine||state.profile.role==='平台管理员'?`<button data-action="delete-post" data-id="${p.id}">删除</button>`:''}</div>${(state.comments[p.id]||[]).length?`<div class="comments">${state.comments[p.id].map(c=>`<div><b>${esc(c.author)}</b>：${esc(c.body)}</div>`).join('')}</div>`:''}</article>`}
function report(){let counts=[['有效工位预约',state.bookings.filter(b=>b.status!=='已取消').length],['活动报名',state.events.length],['资源发布',state.listings.length],['合作与互助申请',state.requests.length]];return `<div class="stats">${counts.map(c=>`<div class="stat"><small>${c[0]}</small><b>${c[1]}</b><small>当前浏览器累计</small></div>`).join('')}</div><div class="panel" style="margin-bottom:22px"><div class="cardhead"><h3>社区参与概览</h3>${btn('导出记录 JSON','export','secondary tiny')}</div>${counts.map(c=>`<div class="reportbar"><span>${c[0]}</span><div class="bartrack"><i style="width:${c[1]/Math.max(1,...counts.map(c=>c[1]))*100}%"></i></div><b>${c[1]}</b></div>`).join('')}<small>统计仅反映本机演示操作，不代表真实平台运营数据。</small></div>`}
function modal(title,body,foot=''){let d=$('#modal');d.innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="close" data-close aria-label="关闭">×</button></div>${body}${foot?`<div class="modalfoot">${foot}</div>`:''}`;if(!d.open)d.showModal();bind(d);d.querySelector('[data-close]').onclick=()=>d.close()}
const close=()=>$('#modal').close();
function requestForm(kind,target){if(state.requests.some(r=>r.kind===kind&&r.target===target&&r.status==='待处理'))return toast('这项申请正在等待处理，可在「我的申请」查看。');modal(`${kind}申请`,`<form id="request-form"><div class="summary">${esc(target)}</div><label class="field">说说你的想法<textarea name="note" required maxlength="300" placeholder="介绍你的需求、时间或合作想法…"></textarea></label><input type="hidden" name="kind" value="${esc(kind)}"><input type="hidden" name="target" value="${esc(target)}"><p class="help">演示操作，仅保存本机记录，不发送真实消息。</p><button class="btn">提交申请</button></form>`);$('#request-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);state.requests.push({id:uid(),kind:f.get('kind'),target:f.get('target'),note:f.get('note'),date:datePlus(0),status:'待处理'});save();close();render();toast('申请已保存，可在用户管理中查看。')}}
function bookingModal(id){currentSpace=spaces.find(s=>s.id===id);seat='';modal('预约 · '+currentSpace.name,`<form id="booking-form"><div class="formgrid"><label class="field">使用日期<input type="date" id="book-date" name="date" min="${datePlus(0)}" value="${datePlus(0)}" required></label><label class="field">使用时段<select id="book-time" name="time"><option>09:00–18:00</option><option>09:00–13:00</option><option>14:00–18:00</option></select></label></div><div class="cardhead"><b>选择你的工位</b><small>浅绿可选 · 灰色已占用</small></div><div class="seats" id="seats"></div><div class="summary">日票 ¥${currentSpace.price} · 半日票 ¥${Math.ceil(currentSpace.price*.65)}<br>位置：${currentSpace.place} · ${currentSpace.area}<br><span id="selected-seat">请先选择工位</span></div><p class="help">演示预约，不产生真实订单或付款。</p><button class="btn" type="submit">确认预约</button><p class="error" id="book-error" role="alert"></p></form>`);drawSeats();$('#book-date').onchange=$('#book-time').onchange=()=>{seat='';drawSeats()};$('#booking-form').onsubmit=e=>{e.preventDefault();if(!seat){$('#book-error').textContent='请先选择一个可用工位。';return}let f=new FormData(e.target);if(f.get('date')<datePlus(0)){ $('#book-error').textContent='请选择今天或之后的日期。';return }state.bookings.push({id:uid(),space:currentSpace.id,name:currentSpace.name,seat,date:f.get('date'),time:f.get('time'),price:f.get('time')==='09:00–18:00'?currentSpace.price:Math.ceil(currentSpace.price*.65),status:'待签到'});save();close();go('desk','我的预约');toast('预约成功，工位已为你留好。')}}
function drawSeats(){let date=$('#book-date').value,time=$('#book-time').value;$('#seats').innerHTML=Array.from({length:12},(_,i)=>{let n=String(i+1).padStart(2,'0'),busy=['03','08'].includes(n)||state.bookings.some(b=>b.space===currentSpace.id&&b.date===date&&b.seat===n&&!['已取消','已结束'].includes(b.status)&&(b.time===time||b.time==='09:00–18:00'||time==='09:00–18:00'));return `<button type="button" class="seat ${seat===n?'selected':''}" data-seat="${n}" ${busy?'disabled':''}>${icon('desk')}<br>${n}</button>`}).join('');$('#selected-seat').textContent=seat?`已选择 ${seat} 号工位`:'请先选择工位';$('#seats').querySelectorAll('[data-seat]').forEach(b=>b.onclick=()=>{seat=b.dataset.seat;drawSeats()})}
function eventModal(id){let a=activities.find(a=>a.id===id),joined=state.events.includes(id);modal(a.name,`<div class="art" style="border-radius:10px;margin-bottom:20px">${landscape()}</div><p class="intro">${a.desc}</p><div class="summary">时间：${eventDate(a)} ${a.time}<br>地点：${a.place}<br>费用：${a.price?'¥'+a.price:'免费'} · 活动容量：${a.cap} 人<br>准备：舒适衣物、自备水杯；户外活动留意天气。</div><p class="help">报名为演示记录，不向主办方发送信息或收取费用。</p>`,btn(joined?'取消报名':'确认报名',joined?'cancel-event':'join-event','',`data-id="${id}"`))}
function tripDetail(t){let v=villages.find(v=>v.id===t.village);modal(`${esc(t.name)} · ${t.days} 天行程`,`<div class="summary">${t.date} 出发 · ${esc(t.transport)}<br>每日预算 ¥${t.budget} · 总预算 ¥${t.budget*t.days}<br>${t.budget<v.budget?'预算低于示例日均开销，建议缩减住宿或交通支出。':'预算与示例日均开销相匹配，可保留弹性费用。'}</div><div class="timeline">${Array.from({length:t.days},(_,i)=>`<div class="timelineitem"><small>DAY ${i+1}</small><h3>${i===0?'抵达村庄，熟悉环境':i===t.days-1?'整理收获，从容返程':'把时间交还给自己'}</h3><p>09:00 ${t.pace==='在地文化探索'?'探访村庄，体验在地文化':'共享工位 · 专注工作'}<br>12:00 村里午餐 / 午休<br>14:00 ${t.pace==='专注远程办公'?'继续办公，完成项目':'竹林散步 / 农事体验'}<br>17:00 ${i===t.days-1?'归还借用物品，准备返程':'社区交流，自由安排'}</p></div>`).join('')}</div><p class="help">规则生成的参考行程，未接入地图导航、实时路况或住宿预订。</p>`)}
function adoptModal(id){let joined=state.adoptions.includes(id);modal(id==='rice'?'余村共享稻田 · 生长档案':'安吉白茶树 · 生长档案',`<div class="art" style="border-radius:10px">${landscape('farm')}</div><div class="summary" style="margin-top:18px">示例认养周期：一季 · 日常养护由合作农户负责<br>参考费用：¥${id==='rice'?299:199} · ${joined?'已保存认养意向':'未认养'}<br>实际付款 ¥0 · 实际收益 ¥0</div><h3>这一季的生长记录</h3><div class="timeline"><div class="timelineitem"><small>示例记录 01</small><h3>完成日常巡田</h3><p>观察叶色与土壤，确认灌溉设施运行正常。</p></div><div class="timelineitem"><small>示例记录 02</small><h3>一起等待收获</h3><p>后续由村民更新生长动态与收获情况。</p></div>${state.approvals.filter(a=>a.kind==='认养动态'&&a.status==='已通过').map(a=>`<div class="timelineitem"><small>社区更新</small><h3>${esc(a.title)}</h3><p>${esc(a.desc)}</p></div>`).join('')}</div><p class="help">当前仅演示认养意向与生长记录；未签订合同、收取费用或承诺收益。</p>`,joined?btn('取消认养意向','cancel-adopt','secondary',`data-id="${id}"`):btn('保存认养意向','confirm-adopt','',`data-id="${id}"`))}
function approvalForm(kind){modal(kind,`<form id="approval-form"><label class="field">${kind==='资格认证'?'组织 / 企业名称':'标题'}<input name="title" maxlength="60" required></label>${kind==='兼职项目'?'<label class="field">项目预算<input name="pay" maxlength="40" placeholder="例如：¥ 2,000 / 项目" required></label>':''}${kind==='活动申请'?`<div class="formgrid"><label class="field">活动日期<input name="date" type="date" min="${datePlus(0)}" value="${datePlus(3)}" required></label><label class="field">时段<input name="time" value="14:00–16:00" maxlength="30" required></label></div><label class="field">活动地点<input name="place" maxlength="60" required></label>`:''}<label class="field">${kind==='活动申请'?'活动安排（时间、地点、内容、人员范围与安全措施）':kind==='资格认证'?'业务介绍（请勿填写身份证号等敏感资料）':'详细说明'}<textarea name="desc" maxlength="1000" required></textarea></label><p class="help">提交后进入社区审核队列。可切换平台管理员演示审核流程。</p><button class="btn">提交审核</button></form>`);$('#approval-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),id=uid();state.approvals.push({id,kind,title:f.get('title'),desc:f.get('desc'),pay:f.get('pay'),date:f.get('date'),time:f.get('time'),place:f.get('place'),status:'待审核'});if(kind==='资格认证')state.certs.push({id,org:f.get('title'),role:state.profile.role,status:'待审核'});save();close();render();toast('已提交，可在社区管理查看审核状态。')}}
function bind(root=document){root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;query='';filter='全部';render()});root.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset));let search=root.querySelector('#search');if(search)search.oninput=()=>{query=search.value;$('#results').innerHTML=page==='desk'?deskResults():resourceResults();bind($('#results'))};let pf=root.querySelector('#profile-form');if(pf)pf.onsubmit=e=>{e.preventDefault();let f=new FormData(pf);if(!f.get('name').trim())return toast('昵称不能只包含空格。');Object.assign(state.profile,{name:f.get('name').trim(),skill:f.get('skill'),bio:f.get('bio')});save();render();toast('个人资料已更新。')};let tf=root.querySelector('#trip-form');if(tf)tf.onsubmit=e=>{e.preventDefault();let f=new FormData(tf);if(f.get('date')<datePlus(0))return toast('请选择今天或之后的出发日期。');let t={id:uid(),village:f.get('village'),name:villages.find(v=>v.id===f.get('village')).name,date:f.get('date'),days:+f.get('days'),budget:+f.get('budget'),pace:f.get('pace'),transport:f.get('transport')};state.trips.push(t);save();go('map','我的行程');tripDetail(t)}}
function action(a,d){switch(a){case'menu':$('.sidebar').classList.toggle('open');break;case'notifications':modal('你的消息',`<div class="summary">工位预约 ${state.bookings.filter(b=>b.status==='待签到').length} 条待签到<br>我的业务申请 ${state.requests.filter(r=>r.status==='待处理').length} 条待处理<br>社区审核 ${state.approvals.filter(r=>r.status==='待审核').length} 条待审核</div><p class="intro">所有消息均来自本机演示操作。</p>`);break;case'book':bookingModal(d.id);break;case'booking-status':{let b=state.bookings.find(b=>b.id===d.id);if(d.next==='使用中'&&b.status==='待签到'&&b.date!==datePlus(0))return toast('请在预约当天签到。');b.status=d.next;save();render();toast('工位状态已更新为「'+d.next+'」。');break}case'village':{let v=villages.find(v=>v.id===d.id);modal(v.name,`<div class="art">${landscape()}</div><p class="intro" style="margin-top:15px">${v.desc}</p><div class="summary">示例网络：${v.net} Mbps<br>生活预算：约 ¥${v.budget} / 日<br>交通方式：公共交通转接驳 / 自驾<br>住宿选择：村居民宿、共居空间<br>体验方向：自然步道、在地农事、社区交流</div><p class="help">示例资料，出行前需核实实际交通、住宿与网络条件。</p>`,btn('为这里规划行程','plan-village','',`data-id="${v.id}"`));break}case'plan-village':close();go('map','行程规划');$('#trip-form [name=village]').value=d.id;break;case'trip-detail':tripDetail(state.trips.find(t=>t.id===d.id));break;case'delete-trip':state.trips=state.trips.filter(t=>t.id!==d.id);save();render();toast('行程已删除。');break;case'request':requestForm(d.kind,d.target);break;case'repair':requestForm('设施报修',d.target);break;case'withdraw':state.requests.find(r=>r.id===d.id).status='已撤回';save();render();toast('申请已撤回。');break;case'publish-resource':modal('分享一份资源',`<form id="resource-form"><div class="formgrid"><label class="field">资源类型<select name="kind"><option>闲置交换</option><option>技能互助</option></select></label><label class="field">交换方式 / 价格<input name="offer" placeholder="例如：交换台灯 / ¥50" maxlength="40" required></label></div><label class="field">资源名称<input name="name" maxlength="50" required></label><label class="field">详细介绍<textarea name="desc" maxlength="500" placeholder="介绍物品状态、技能或期待交换的内容" required></textarea></label><button class="btn">发布资源</button></form>`);$('#resource-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);state.listings.push({id:uid(),name:f.get('name'),desc:f.get('desc'),kind:f.get('kind'),offer:f.get('offer'),owner:state.profile.name,mine:true});save();close();go('box','我的发布');toast('资源已发布。')};break;case'remove-listing':state.listings=state.listings.filter(i=>i.id!==d.id);save();render();toast('资源已撤下。');break;case'event':eventModal(d.id);break;case'join-event':if(!state.events.includes(d.id))state.events.push(d.id);save();close();render();toast('报名已记录，期待在乡村相遇。');break;case'cancel-event':state.events=state.events.filter(id=>id!==d.id);save();close();render();toast('报名已取消。');break;case'adopt':adoptModal(d.id);break;case'confirm-adopt':if(!state.adoptions.includes(d.id))state.adoptions.push(d.id);save();close();render();toast('认养意向已保存，未产生付款。');break;case'cancel-adopt':state.adoptions=state.adoptions.filter(id=>id!==d.id);save();close();render();toast('认养意向已取消。');break;case'role':state.profile.role=d.role;save();render();toast('已切换为'+d.role+'演示视角。');break;case'certify':approvalForm('资格认证');break;case'growth':approvalForm('认养动态');break;case'propose-event':approvalForm('活动申请');break;case'publish-job':approvalForm('兼职项目');break;case'approve':{if(state.profile.role!=='平台管理员')return toast('请切换平台管理员演示角色。');state.approvals.find(x=>x.id===d.id).status=d.next;let c=state.certs.find(x=>x.id===d.id);if(c)c.status=d.next;save();render();toast('审核结果已保存。');break}case'handle-request':case'reject-request':if(state.profile.role!=='平台管理员')return;state.requests.find(r=>r.id===d.id).status=a==='handle-request'?'已受理':'已驳回';save();render();toast('申请处理结果已保存。');break;case'like':state.likes.includes(d.id)?state.likes=state.likes.filter(id=>id!==d.id):state.likes.push(d.id);save();render();break;case'comment':modal('给邻居留一句话',`<form id="comment-form"><label class="field">留言<textarea name="body" maxlength="300" required placeholder="分享你的想法，善意交流。"></textarea></label><button class="btn">发表留言</button></form>`);$('#comment-form').onsubmit=e=>{e.preventDefault();let body=new FormData(e.target).get('body').trim();if(!body)return;state.comments[d.id]??=[];state.comments[d.id].push({author:state.profile.name,body});save();close();render();toast('留言已发表。')};break;case'post':modal('记录一段乡野日常',`<form id="post-form"><label class="field">主题<select name="topic"><option>乡野日常</option><option>共创招募</option><option>在地发现</option><option>邻里求助</option></select></label><label class="field">标题<input name="title" maxlength="60" required></label><label class="field">正文<textarea name="body" maxlength="2000" required placeholder="今天，有什么想和邻居分享的？"></textarea></label><button class="btn">发布动态</button></form>`);$('#post-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);state.posts.push({id:uid(),author:state.profile.name,title:f.get('title'),body:f.get('body'),topic:f.get('topic'),likes:0,date:datePlus(0),mine:true});save();close();go('community');toast('动态已发布。')};break;case'delete-post':if(seedPosts.some(p=>p.id===d.id)){if(state.profile.role!=='平台管理员')return;state.hiddenPosts.push(d.id)}state.posts=state.posts.filter(p=>p.id!==d.id);delete state.comments[d.id];save();render();toast('动态已删除。');break;case'read-rules':state.readRules=true;save();render();toast('谢谢你，一起让社区更美好。');break;case'export':{let blob=new Blob([JSON.stringify({app:'乡约码上行',exported:new Date().toISOString(),scope:'当前浏览器演示数据',...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='乡约码上行-演示记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('演示记录已导出。');break}}}

